#!/usr/bin/env node
// Read-only gate. Run: node check-ghost-release.cjs <launcher-source-root> [app.asar]
const fs=require('node:fs');const path=require('node:path');const {createRequire}=require('node:module');
const root=path.resolve(process.argv[2]||'.');const errors=[];const checks=[];
function read(p){return fs.readFileSync(path.join(root,p),'utf8');}
function check(ok,label){checks.push({label,passed:!!ok});if(!ok)errors.push(label);}
try{
 const pkg=JSON.parse(read('package.json'));const info=read('src/_managerinf/ManagerInformation.ts');
 const literal=info.match(/VERSION\s*:\s*VersionNumber\s*=\s*new VersionNumber\(['"](\d+\.\d+\.\d+)['"]\)/);
 const derived=/import\s*\{\s*version\s+as\s+applicationVersion\s*\}\s*from\s*['"]\.\.\/\.\.\/package\.json['"]/.test(info)&&/VERSION\s*:\s*VersionNumber\s*=\s*new VersionNumber\(applicationVersion\)/.test(info);
 check(literal?literal[1]===pkg.version:derived,`source display version ${literal?.[1]||'(derived)'} equals package ${pkg.version}`);
 const core=read('src/ghost/GhostRepositoryCore.ts');const origin=core.match(/export const GHOST_ORIGIN\s*=\s*['"]([^'"]+)['"]/);
 check(origin?.[1]==='https://sukgicalm-lang.github.io/ghost-valheim-vault','current feed base is the public owned Pages path');
 const interval=core.match(/GHOST_REFRESH_INTERVAL\s*=\s*([\d_]+)/);
 check(interval&&Number(interval[1].replaceAll('_',''))===30000,'independent Ghost check interval is30seconds');
 const repo=read('src/ghost/GhostRepository.ts');check(repo.includes('ghost_check')&&repo.includes('no-cache'),'feed request uses unique cache key and cache directives');
 const setup=JSON.parse(read('src/ghost/GhostSetupBundle.json')).setup;check(setup.schema===1&&setup.packages.length===29,'source contains the complete 29-package required setup');
 if(process.argv[3]){
  const req=createRequire(path.join(root,'package.json'));const asar=req('@electron/asar');const archive=path.resolve(process.argv[3]);const embedded=JSON.parse(asar.extractFile(archive,'package.json').toString());
  check(embedded.version===pkg.version,`actual app.asar version ${embedded.version} equals source ${pkg.version}`);
  const backend=asar.extractFile(archive,embedded.main.replace(/^\.\//,'')).toString();
  check(backend.includes('client-release.json')&&backend.includes('ghost-self-update-prepare')&&backend.includes('Install-GhostRuntime')&&backend.includes('ready.txt'),'actual backend archive contains verified automatic client update and Windows replacement helper');
  check(backend.includes('ghost-is-game-running'),'actual backend guards required setup while Valheim is running');
  let automatic=false;
  let direct=false,bypass=false,oldRequest=false;const displayed=new Set();
  for(const file of asar.listPackage(archive).map(f=>f.replaceAll('\\','/')).filter(f=>f.startsWith('/assets/')&&f.endsWith('.js'))){const t=asar.extractFile(archive,file.slice(1)).toString();automatic ||=t.includes('setup-release.json');direct ||=t.includes('https://sukgicalm-lang.github.io/ghost-valheim-vault');bypass ||=t.includes('ghost_check');oldRequest ||=t.includes('tail054318.ts.net/releases.json');for(const m of t.matchAll(/VERSION\s*=\s*new\s+[\w$]+\((['"][^'"]+['"]|[\w$]+)\)/g)){const expr=m[1];if(/^['"]/.test(expr))displayed.add(expr.slice(1,-1));else{const safe=expr.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');const assignment=t.match(new RegExp('(?:var|const|let|,)\\s*'+safe+'\\s*=\\s*[\"\'](\\d+\\.\\d+\\.\\d+)[\"\']'));displayed.add(assignment?assignment[1]:'UNRESOLVED:'+expr);}}}
  check(automatic,'actual renderer contains automatic required setup feed');
  check(direct&&bypass&&!oldRequest,'actual archive includes direct feed/cache key and no old bridge feed URL');
  check(displayed.size>0&&[...displayed].every(v=>v===pkg.version),`actual archive display literals [${[...displayed].join(',')}] equal package ${pkg.version}`);
 }
 console.log(JSON.stringify({version:pkg.version,result:errors.length?'FAIL':'PASS',checks,errors},null,2));process.exitCode=errors.length?1:0;
}catch(e){console.error(JSON.stringify({result:'FAIL',error:e.message}));process.exitCode=1;}

import {createHash} from 'node:crypto';
import {createWriteStream} from 'node:fs';
import {rm} from 'node:fs/promises';
import {Readable, Transform} from 'node:stream';
import {pipeline} from 'node:stream/promises';

export const GHOST_CLIENT_FEED = 'https://sukgicalm-lang.github.io/ghost-valheim-vault/client-release.json';
export interface GhostClientRelease { version: string; bytes: number; sha256: string; downloadUrl: string; }
export type GhostSelfUpdatePhase = 'checking' | 'downloading' | 'installing' | 'error' | 'idle';
export interface GhostSelfUpdateState { phase: GhostSelfUpdatePhase; current: string; target: string; progress: number; message: string; }
export function compareClientVersions(a: string, b: string): number {
    if (![a,b].every(v => /^\d+\.\d+\.\d+$/.test(v))) throw new Error('Invalid launcher version');
    const aa=a.split('.').map(Number), bb=b.split('.').map(Number);
    for(let i=0;i<3;i++) if(aa[i]!==bb[i]) return aa[i]!-bb[i]!;
    return 0;
}
export function validateClientRelease(value: unknown): GhostClientRelease {
    const r=value as GhostClientRelease;
    if(!r || typeof r.version!=='string' || !/^\d+\.\d+\.\d+$/.test(r.version)) throw new Error('런처 배포 버전이 올바르지 않습니다.');
    if(!Number.isSafeInteger(r.bytes) || r.bytes<=0 || r.bytes>512*1024*1024) throw new Error('런처 배포 크기가 올바르지 않습니다.');
    if(typeof r.sha256!=='string' || !/^[a-f0-9]{64}$/.test(r.sha256)) throw new Error('런처 배포 검증값이 올바르지 않습니다.');
    if(r.downloadUrl!==`https://github.com/sukgicalm-lang/ghost-valheim-vault/releases/download/client-${r.version}/GhostR2-Windows-${r.version}.zip`) throw new Error('허용되지 않은 런처 배포 경로입니다.');
    return {version:r.version,bytes:r.bytes,sha256:r.sha256,downloadUrl:r.downloadUrl};
}
export function safeInstallProtocol(value: string | null): string {
    return value && /^ghostvault:\/\/v1\/install\/(Ghost-GhostValheimSuite|Ghost-GhostSmelterControl)\/(latest|\d+\.\d+\.\d+)\/?$/.test(value) ? value : '';
}
export async function downloadVerifiedClient(
    release: GhostClientRelease, destination: string,
    fetcher: (url: string, init: any) => Promise<any>, progress: (percent: number) => void,
): Promise<void> {
    const r=validateClientRelease(release);
    const abort=new AbortController(), timeout=setTimeout(()=>abort.abort(),12*60*1000);
    try {
        const response=await fetcher(r.downloadUrl,{signal:abort.signal,cache:'no-store'});
        if(!response.ok || !response.body) throw new Error('런처 다운로드에 실패했습니다.');
        const length=response.headers?.get('content-length');
        if(length && Number(length)!==r.bytes) throw new Error('런처 다운로드 크기가 다릅니다.');
        const hash=createHash('sha256');let count=0,last=-1;
        const verify=new Transform({transform(chunk,_encoding,callback){
            count+=chunk.length;
            if(count>r.bytes){callback(new Error('런처 다운로드 크기가 초과되었습니다.'));return;}
            hash.update(chunk);const percent=Math.floor(count/r.bytes*100);
            if(percent!==last){last=percent;progress(percent);}
            callback(null,chunk);
        }});
        await pipeline(Readable.fromWeb(response.body),verify,createWriteStream(destination,{flags:'wx',mode:0o600}));
        if(count!==r.bytes || hash.digest('hex')!==r.sha256) throw new Error('런처 파일의 크기 또는 SHA-256이 일치하지 않습니다.');
    } catch(error) { await rm(destination,{force:true}).catch(()=>{});throw error; }
    finally {clearTimeout(timeout);}
}

export const GHOST_SELF_UPDATE_HELPER = String.raw`param(
    [switch]$FunctionsOnly,
    [int]$ParentProcessId,
    [string]$ArchivePath,
    [string]$ExpectedHash,
    [string]$Version,
    [string]$CurrentExePath,
    [string]$ReadyPath,
    [string]$PendingProtocol = ''
)
$ErrorActionPreference = 'Stop'
Add-Type -AssemblyName System.IO.Compression.FileSystem

function Install-GhostRuntime([string]$ZipPath,[string]$Hash,[string]$TargetVersion,[string]$InstallBase) {
    if ($TargetVersion -notmatch '^\d+\.\d+\.\d+$' -or $Hash -notmatch '^[a-f0-9]{64}$') { throw 'Invalid update identity' }
    if ((Get-FileHash -LiteralPath $ZipPath -Algorithm SHA256).Hash.ToLowerInvariant() -cne $Hash) { throw 'Update SHA-256 mismatch' }
    $archive = [IO.Compression.ZipFile]::OpenRead($ZipPath)
    try {
        foreach ($entry in $archive.Entries) {
            $name = $entry.FullName.Replace('\','/')
            if ($name -match '(^/|^[A-Za-z]:|(^|/)\.\.(/|$)|:)') { throw 'Unsafe update ZIP path' }
        }
    } finally { $archive.Dispose() }
    $staging = Join-Path (Split-Path $ZipPath -Parent) ('staging-' + [guid]::NewGuid().ToString('N'))
    [IO.Compression.ZipFile]::ExtractToDirectory($ZipPath,$staging)
    if (-not (Test-Path -LiteralPath (Join-Path $staging 'GhostR2.exe') -PathType Leaf) -or -not (Test-Path -LiteralPath (Join-Path $staging 'resources\app.asar') -PathType Leaf)) {
        Remove-Item -LiteralPath $staging -Recurse -Force -ErrorAction SilentlyContinue
        throw 'Incomplete launcher payload'
    }
    New-Item -ItemType Directory -Path $InstallBase -Force | Out-Null
    $destination = Join-Path $InstallBase $TargetVersion
    $previous = $null
    if (Test-Path -LiteralPath $destination) {
        $previous = $destination + '.previous-' + [guid]::NewGuid().ToString('N')
        Move-Item -LiteralPath $destination -Destination $previous
    }
    try { Move-Item -LiteralPath $staging -Destination $destination }
    catch {
        if ($previous -and -not (Test-Path -LiteralPath $destination)) { Move-Item -LiteralPath $previous -Destination $destination }
        throw
    }
    return (Join-Path $destination 'GhostR2.exe')
}
function Set-GhostRuntimeLinks([string]$ExePath) {
    $protocolKey = 'HKCU:\Software\Classes\ghostvault'
    New-Item -Path ($protocolKey + '\shell\open\command') -Force | Out-Null
    Set-Item -Path $protocolKey -Value 'URL:Ghost Vault install link'
    New-ItemProperty -Path $protocolKey -Name 'URL Protocol' -PropertyType String -Value '' -Force | Out-Null
    Set-Item -Path ($protocolKey + '\shell\open\command') -Value ('"' + $ExePath + '" "%1"')
    $shell = New-Object -ComObject WScript.Shell
    $shortcut = $shell.CreateShortcut((Join-Path ([Environment]::GetFolderPath('Desktop')) 'Ghost r2modman.lnk'))
    $shortcut.TargetPath = $ExePath
    $shortcut.WorkingDirectory = Split-Path $ExePath -Parent
    $shortcut.Save()
}
function Start-GhostRuntime([string]$ExePath,[string]$InstallProtocol) {
    $launch = @{FilePath=$ExePath;WorkingDirectory=(Split-Path $ExePath -Parent);ErrorAction='Stop'}
    if ($InstallProtocol -and $InstallProtocol -match '^ghostvault://v1/install/(Ghost-GhostValheimSuite|Ghost-GhostSmelterControl)/(latest|\d+\.\d+\.\d+)/?$') { $launch.ArgumentList = $InstallProtocol }
    Start-Process @launch | Out-Null
}
if ($FunctionsOnly) { return }
$installBase = Join-Path $env:LOCALAPPDATA 'GhostR2'
$record = Join-Path $installBase 'self-update-result.json'
try {
    if ($env:OS -ne 'Windows_NT' -or $ParentProcessId -le 0 -or $Version -notmatch '^\d+\.\d+\.\d+$' -or $ExpectedHash -notmatch '^[a-f0-9]{64}$') { throw 'Invalid update request' }
    if (-not (Test-Path -LiteralPath $ArchivePath -PathType Leaf) -or -not (Test-Path -LiteralPath $CurrentExePath -PathType Leaf)) { throw 'Missing update files' }
    if ((Get-FileHash -LiteralPath $ArchivePath -Algorithm SHA256).Hash.ToLowerInvariant() -cne $ExpectedHash) { throw 'Update SHA-256 mismatch' }
    New-Item -ItemType Directory -Path $installBase -Force | Out-Null
    [IO.File]::WriteAllText($ReadyPath,'ready')
    $parent = Get-Process -Id $ParentProcessId -ErrorAction SilentlyContinue
    if ($parent) {
        try { Wait-Process -Id $ParentProcessId -Timeout 60 -ErrorAction Stop }
        catch { if (Get-Process -Id $ParentProcessId -ErrorAction SilentlyContinue) { throw } }
    }
    $exe = Install-GhostRuntime $ArchivePath $ExpectedHash $Version $installBase
    Set-GhostRuntimeLinks $exe
    @{status='success';version=$Version;time=[DateTimeOffset]::UtcNow.ToUnixTimeMilliseconds()} | ConvertTo-Json | Set-Content -LiteralPath $record -Encoding UTF8
    Start-GhostRuntime $exe $PendingProtocol
    Remove-Item -LiteralPath $ArchivePath -Force -ErrorAction SilentlyContinue
} catch {
    New-Item -ItemType Directory -Path $installBase -Force | Out-Null
    @{status='failed';version=$Version;time=[DateTimeOffset]::UtcNow.ToUnixTimeMilliseconds();message=$_.Exception.Message} | ConvertTo-Json | Set-Content -LiteralPath $record -Encoding UTF8
    try {
        if (-not (Get-Process -Id $ParentProcessId -ErrorAction SilentlyContinue)) {
            Set-GhostRuntimeLinks $CurrentExePath
            Start-GhostRuntime $CurrentExePath $PendingProtocol
        }
    } catch { }
    exit 1
}
`;

import {app, BrowserWindow, ipcMain, net} from 'electron';
import {mkdtemp, readFile, writeFile, access, rm} from 'node:fs/promises';
import path from 'node:path';
import os from 'node:os';
import {spawn} from 'node:child_process';
import {GHOST_SELF_UPDATE_HELPER} from './GhostSelfUpdateHelper';
import {GHOST_CLIENT_FEED, compareClientVersions, validateClientRelease, downloadVerifiedClient, safeInstallProtocol, type GhostSelfUpdateState} from './GhostSelfUpdateCore';

export function registerGhostSelfUpdater(window: BrowserWindow, pendingProtocol: () => string | null) {
    let state: GhostSelfUpdateState={phase:'checking',current:app.getVersion(),target:'',progress:0,message:'런처 새 버전을 확인하고 있습니다.'};
    let ongoing: Promise<boolean> | undefined;
    let decision: ((value:'retry'|'continue')=>void) | undefined;
    function publish(patch: Partial<GhostSelfUpdateState>) {
        state={...state,...patch};
        if(!window.isDestroyed()) window.webContents.send('ghost-self-update-state',state);
    }
    const allowed=(event: Electron.IpcMainInvokeEvent)=>{
        if(event.sender!==window.webContents) throw new Error('Unexpected update caller');
    };
    async function run(): Promise<boolean> {
        if(process.platform!=='win32' || !app.isPackaged){publish({phase:'idle'});return true;}
        for(;;){
            let temporary='';
            let validatedNewRelease=false;
            try {
                publish({phase:'checking',progress:0,message:'런처 새 버전을 확인하고 있습니다.'});
                const abort=new AbortController(), timeout=setTimeout(()=>abort.abort(),8000);
                let release;
                try {
                    const response=await net.fetch(GHOST_CLIENT_FEED+'?check='+Date.now(),{cache:'no-store',signal:abort.signal});
                    if(!response.ok) throw new Error('Launcher feed unavailable');
                    release=validateClientRelease(await response.json());
                } finally {clearTimeout(timeout);}
                if(compareClientVersions(release.version,app.getVersion())<=0){publish({phase:'idle'});return true;}
                validatedNewRelease=true;
                publish({target:release.version});
                try {
                    const recordPath=path.join(process.env.LOCALAPPDATA||'', 'GhostR2/self-update-result.json');
                    const record=JSON.parse((await readFile(recordPath,'utf8')).replace(/^\ufeff/,''));
                    if(record.status==='failed' && record.version===release.version && Date.now()-record.time<60*60*1000){
                        publish({phase:'error',message:'이전 자동 업데이트가 완료되지 않았습니다. 다시 시도하거나 현재 버전으로 계속할 수 있습니다.'});
                        const answer=await new Promise<'retry'|'continue'>(resolve=>decision=resolve);
                        decision=undefined;
                        if(answer==='continue'){publish({phase:'idle'});return true;}
                        await rm(recordPath,{force:true});
                    }
                } catch { /* No previous update failure. */ }
                temporary=await mkdtemp(path.join(os.tmpdir(),'GhostR2-update-'));
                const archive=path.join(temporary,'runtime.zip');
                publish({phase:'downloading',message:`Ghost r2 ${release.version} 업데이트를 내려받고 있습니다.`});
                await downloadVerifiedClient(release,archive,(url,init)=>net.fetch(url,init),progress=>publish({progress}));
                const helper=path.join(temporary,'update.ps1'), ready=path.join(temporary,'ready.txt');
                await writeFile(helper,'\ufeff'+GHOST_SELF_UPDATE_HELPER,{encoding:'utf8',mode:0o600});
                publish({phase:'installing',progress:100,message:'파일 검증이 끝났습니다. 런처를 교체한 뒤 자동으로 다시 실행합니다.'});
                const powershell=path.join(process.env.SystemRoot||'C:\\Windows','System32/WindowsPowerShell/v1.0/powershell.exe');
                const args=['-NoProfile','-NonInteractive','-ExecutionPolicy','Bypass','-File',helper,
                    '-ParentProcessId',String(process.pid),'-ArchivePath',archive,'-ExpectedHash',release.sha256,
                    '-Version',release.version,'-CurrentExePath',app.getPath('exe'),'-ReadyPath',ready];
                const installProtocol=safeInstallProtocol(pendingProtocol());
                if(installProtocol)args.push('-PendingProtocol',installProtocol);
                const child=spawn(powershell,args,{detached:true,stdio:'ignore',windowsHide:true});
                let helperError: Error | undefined;
                child.once('error',error=>helperError=error);
                let helperReady=false;
                for(let i=0;i<300;i++){
                    if(helperError)throw helperError;
                    try {await access(ready);helperReady=true;break;} catch { }
                    if(child.exitCode!==null)throw new Error('런처 교체 도구를 시작하지 못했습니다.');
                    await new Promise(resolve=>setTimeout(resolve,100));
                }
                if(!helperReady)throw new Error('런처 교체 준비 시간이 초과되었습니다.');
                child.unref();
                app.quit();
                return false;
            } catch(error) {
                if(temporary)await rm(temporary,{recursive:true,force:true}).catch(()=>{});
                // Offline startup must stay usable. A validated newer release that
                // failed to download is shown explicitly, without an update loop.
                if(!validatedNewRelease){publish({phase:'idle'});return true;}
                publish({phase:'error',message:'자동 업데이트를 완료하지 못했습니다. '+(error instanceof Error?error.message:'다시 시도해 주세요.')});
                const answer=await new Promise<'retry'|'continue'>(resolve=>decision=resolve);
                decision=undefined;
                if(answer==='continue'){publish({phase:'idle'});return true;}
            }
        }
    }
    window.once('closed',()=>{
        for(const channel of ['ghost-self-update-state','ghost-self-update-prepare','ghost-self-update-decision'])ipcMain.removeHandler(channel);
    });
    ipcMain.handle('ghost-self-update-state',event=>{allowed(event);return state;});
    ipcMain.handle('ghost-self-update-prepare',event=>{allowed(event);return ongoing ||=run();});
    ipcMain.handle('ghost-self-update-decision',(event,value)=>{
        allowed(event);
        if(state.phase==='error' && (value==='retry'||value==='continue')){const resolve=decision;decision=undefined;resolve?.(value);}
    });
}

import { app, BrowserWindow, ipcMain, nativeTheme, protocol, dialog } from 'electron';
import { execFileSync } from 'node:child_process';
import { Listeners } from './ipcListeners';
import {registerGhostSelfUpdater} from './GhostSelfUpdater';
import { Persist } from './window-state-persist';
import path from 'path';
import fs from 'fs';
import { fileURLToPath } from 'url';
import 'app/src-electron/ipc/init-ipc';
import { hookIpc } from 'app/src-electron/ipc/init-ipc';

// @ts-ignore
app.allowRendererProcessReuse = true;

try {
    if (process.platform === 'win32' && nativeTheme.shouldUseDarkColors === true) {
        require('fs').unlinkSync(path.join(app.getPath('userData'), 'DevTools Extensions'));
    }
} catch (_) {
}

/**
 * Set `__statics` path to static files in production;
 * The reason we are setting it here is that the path needs to be evaluated at runtime
 */

const __filename = fileURLToPath(import.meta.url); // get the resolved path to the file
const __dirname = path.dirname(__filename);
const anyGlobal: any = global;

if (process.env.PROD) {
    anyGlobal.__statics = __dirname;
    anyGlobal.__statics = path.join(__dirname, 'statics').replace(/\\/g, '\\\\');
    anyGlobal.__assets = path.join(__dirname, 'assets').replace(/\\/g, '\\\\');
}

let mainWindow: BrowserWindow | null = null;
let installHandlerReady = false;
let pendingInstallUrl: string | null = null;
ipcMain.on('ghost-install-handler-ready', () => {
    installHandlerReady = true;
    if (pendingInstallUrl) dispatchInstallUrl(pendingInstallUrl);
});

function ordinaryR2Running(): boolean {
    if (process.platform !== 'win32') return false;
    // The two managers use the same profile directory. Do not allow concurrent writers.
    try {
        const processes = execFileSync('tasklist.exe', ['/FO', 'CSV', '/NH'], { encoding: 'utf8', windowsHide: true });
        return processes.split(/\r?\n/).some(line => /^"r2modman(?:Plus)?\.exe",/i.test(line));
    } catch { return true; }
}
ipcMain.handle('ghost-ensure-exclusive', () => !ordinaryR2Running());
ipcMain.handle('ghost-is-game-running', () => {
    if(process.platform!=='win32')return false;
    try {return execFileSync('tasklist.exe',['/FO','CSV','/NH'],{encoding:'utf8',windowsHide:true}).split(/\r?\n/).some(line=>/^"valheim(?:_server)?\.exe",/i.test(line));}
    catch{return true;}
});

async function createWindow() {

    const windowSize = Persist.getSize(app, {
        defaultWidth: 1200,
        defaultHeight: 700
    });

    mainWindow = new BrowserWindow({
        width: windowSize.width,
        height: windowSize.height,
        useContentSize: true,
        icon: path.resolve(__dirname, 'icons/icon.png'),
        autoHideMenuBar: !!process.env.PROD,
        webPreferences: {
            preload: path.resolve(
                fileURLToPath(new URL('.', import.meta.url)),
                path.join(process.env.QUASAR_ELECTRON_PRELOAD_FOLDER, 'electron-preload' + process.env.QUASAR_ELECTRON_PRELOAD_EXTENSION)
            ),
            // TODO - Remove and find an appropriate workaround for CORS blocking by Electron
            // Likely workaround is to move network requests to backend
            webSecurity: false
        }
    });

    registerGhostSelfUpdater(mainWindow, () => pendingInstallUrl || extractInstallUrl(process.argv));
    hookIpc(mainWindow);

    if (windowSize.maximized) {
        mainWindow.maximize();
    }

    Persist.handle(mainWindow, app);

    // Initialise client to server communication listener
    new Listeners(mainWindow, app);

    if (process.env.DEV) {
        await mainWindow.loadURL(process.env.APP_URL);
    } else {
        await mainWindow.loadFile('index.html');
    }

    mainWindow.on('closed', () => {
        mainWindow = null;
    });
}

const extractInstallUrl = (argv: string[]): string | null =>
    argv.find((arg) => arg.startsWith('ghostvault://')) ?? null;

function dispatchInstallUrl(url: string | null) {
    if (!url) return;
    pendingInstallUrl = url;
    if (!mainWindow || !installHandlerReady) return;
    const { webContents } = mainWindow;
    if (webContents.isLoading()) {
        webContents.once('did-finish-load', () => ipcMain.emit('install-via-thunderstore', url));
    } else {
        ipcMain.emit('install-via-thunderstore', url);
    }
    pendingInstallUrl = null;
}

if (!app.requestSingleInstanceLock()) {
    app.quit();
} else {
    app.on('second-instance', (_event, argv) => {
        if (mainWindow) {
            if (mainWindow.isMinimized()) mainWindow.restore();
            mainWindow.focus();
        }
        dispatchInstallUrl(extractInstallUrl(argv));
    });

    app.on('ready', async () => {
        if (ordinaryR2Running()) {
            await dialog.showMessageBox({ type: 'warning', title: 'Ghost r2modman', message: '일반 r2modman을 먼저 종료하세요.', detail: '기존 프로필을 안전하게 사용하기 위해 동시에 실행하지 않습니다.' });
            app.quit();
            return;
        }
        await createWindow();
        dispatchInstallUrl(extractInstallUrl(process.argv));
    });
}

