export async function verifyGhostPayload(combo: ThunderstoreCombo, data: ArrayBuffer): Promise<void> {
    const version = combo.getVersion();
    const setupHash = version.getGhostSetupSha256?.() || '';
    if (!isGhostPackage(combo.getMod().getFullName()) && !setupHash) return;
    const expected = isGhostPackage(combo.getMod().getFullName())?version.getGhostSha256():setupHash;
    const url = new URL(version.getDownloadUrl());
    const name=combo.getMod().getFullName();
    const trusted=isGhostPackage(name)?isTrustedGhostDownloadUrl(url.href,version.getVersionNumber().toString(),name):url.href===`https://gcdn.thunderstore.io/live/repository/packages/${name}-${version.getVersionNumber()}.zip`;
    if (!trusted || !/^[a-f0-9]{64}$/.test(expected)) throw new Error('Ghost 다운로드의 출처와 검증 정보를 확인하지 못했습니다.');
    if (data.byteLength !== version.getFileSize()) throw new Error('Ghost 파일 크기가 배포 정보와 다릅니다. 설치를 중단했습니다.');
    const hash = await crypto.subtle.digest('SHA-256', data);
    const actual = Array.from(new Uint8Array(hash), x => x.toString(16).padStart(2, '0')).join('');
    if (actual !== expected) throw new Error('Ghost 파일의 SHA-256이 다릅니다. 설치를 중단했습니다.');
}

export async function backupGhostProfile(combos: ThunderstoreCombo[], profile: ImmutableProfile,allRequired=false): Promise<string|undefined> {
    if (!allRequired && !combos.some(c => isGhostPackage(c.getMod().getFullName()))) return;
    if (!await window.app.ensureGhostExclusive()) throw new Error('일반 r2modman을 종료한 뒤 다시 설치하세요. 기존 프로필에 동시에 쓰지 않도록 중단했습니다.');
    const fs = FsProvider.instance;
    const stamp = new Date().toISOString().replace(/[:.]/g, '-') + '-' + Math.random().toString(36).slice(2, 7);
    const destination = profile.joinToProfilePath('GhostBackups', stamp);
    await fs.mkdirs(destination);
    for (const relative of ['mods.yml', 'BepInEx/config', ...(allRequired&&combos.some(c=>c.getMod().getFullName()==='denikson-BepInExPack_Valheim')?['BepInEx/core','doorstop_config.ini','winhttp.dll','doorstop_libs']:[]), ...combos.filter(c => allRequired||isGhostPackage(c.getMod().getFullName())).flatMap(c => ['BepInEx/plugins/','BepInEx/patchers/'].map(p=>p+c.getMod().getFullName()))]) {
        const source = profile.joinToProfilePath(relative);
        if (!await fs.exists(source)) continue;
        const target = path.join(destination, relative);
        if ((await fs.lstat(source)).isFile()) { await fs.mkdirs(path.dirname(target)); await fs.copyFile(source, target); }
        else { await fs.copyFolder(source, target); }
    }
    await fs.writeFile(path.join(destination, 'backup.json'), JSON.stringify({ profile: profile.getProfileName(), created: stamp, packages: combos.map(c => c.getDependencyString()) }, null, 2));
    return destination;
}

export async function restoreGhostConfiguration(backup:string|undefined,profile:ImmutableProfile):Promise<void>{
    if(!backup)return;
    const source=path.join(backup,'BepInEx/config');
    if(await FsProvider.instance.exists(source))await FsProvider.instance.copyFolder(source,profile.joinToProfilePath('BepInEx/config'));
}

import { reactive } from 'vue';
import axios from 'axios';
import Game from '../model/game/Game';
import * as PackageDb from '../r2mm/manager/PackageDexieStore';
import { syncGhostSmelterRepository } from './GhostSmelterRepository';
import { GHOST_ORIGIN, ghostPackageFromReleases, isGhostGame, normalizeGhostCatalog, validateGhostRelease, compareGhostVersions, GHOST_PACKAGE } from './GhostRepositoryCore';

export const ghostStatus = reactive({ error: '', updated: '', latest: '', pending: false, checking: false });
let ongoing: Promise<void> | undefined;
let lastFetch = 0;
export async function syncGhostRepository(game: Game, force = false): Promise<void> {
    if (!isGhostGame(game.internalFolderName)) return;
    if (ongoing) return ongoing;
    if (!force && Date.now() - lastFetch < 15000) return;
    ghostStatus.checking = true;
    const smelterSync = syncGhostSmelterRepository(game);
    ongoing = (async () => {
        try {
            // Both endpoints bypass the old PC bridge. A unique URL plus explicit
            // request cache directives avoids the previous 10-minute cached reply.
            const nonce = Date.now().toString(36) + Math.random().toString(36).slice(2);
            const options = { timeout: 8000, params: { ghost_check: nonce }, headers: { 'Cache-Control': 'no-cache, no-store, max-age=0', 'Pragma': 'no-cache' } };
            const [latestResult, catalogResult] = await Promise.allSettled([
                axios.get(GHOST_ORIGIN + '/release.json', options),
                axios.get(GHOST_ORIGIN + '/releases.json', options),
            ]);
            let checked = catalogResult.status === 'fulfilled' ? normalizeGhostCatalog(catalogResult.value.data) : [];
            const latest = latestResult.status === 'fulfilled' ? validateGhostRelease(latestResult.value.data) : undefined;
            if (latest) {
                const same = checked.find(r => r.version === latest.version);
                if (same && (same.sha256 !== latest.sha256 || same.bytes !== latest.bytes)) throw new Error('Ghost feed conflict');
                checked = normalizeGhostCatalog([...checked.filter(r => r.version !== latest.version), latest]);
            }
            if (!checked.length) throw new Error('Ghost feed unavailable');
            // If history is temporarily unavailable, retain validated cached versions
            // for profile imports while incorporating the freshly checked latest release.
            if (catalogResult.status === 'rejected') {
                try {
                    const raw = await PackageDb.getPackageFromDatabase(game.internalFolderName, GHOST_PACKAGE);
                    const older = raw.versions.map((v: any) => validateGhostRelease({version: v.version_number, date: v.date_created.slice(0, 10), file: `downloads/Ghost-GhostValheimSuite-${v.version_number}.zip`, bytes: v.file_size, sha256: v.ghost_sha256, notes: v.description, dependencies: v.dependencies}));
                    checked = normalizeGhostCatalog([...checked, ...older.filter((v: any) => !checked.some(r => r.version === v.version))].slice(0, 100));
                } catch { /* No valid cached history yet; the fresh release remains usable. */ }
            }
            const cached = (await PackageDb.getPackagesByNames(game.internalFolderName, [GHOST_PACKAGE]))[0];
            if (cached && compareGhostVersions(cached.getLatestVersion().toString(), checked[0]!.version) > 0) {
                ghostStatus.latest = cached.getLatestVersion().toString();
                throw new Error('Ghost feed is older than the saved catalog');
            }
            await PackageDb.upsertPackageListChunk(game.internalFolderName, [ghostPackageFromReleases(checked)]);
            ghostStatus.latest = checked[0]!.version;
            ghostStatus.error = latest ? '' : '최신 배포 조회에 실패하여 배포 목록을 표시합니다. 다시 확인해 주세요.';
            ghostStatus.updated = new Date().toLocaleTimeString('ko-KR');
            lastFetch = Date.now();
        } catch (error) {
            ghostStatus.error = 'Ghost 사이트에 연결하지 못했습니다. 저장된 정보는 유지합니다.';
            throw error;
        }
    })();
    // Keep the shared refresh pending until both catalogs settle, including
    // suite failures, so profile imports and Update All see the second package.
    const suiteSync = ongoing;
    ongoing = (async () => { try { await suiteSync; } finally { await smelterSync; } })();
    try { await ongoing; } finally { ongoing = undefined; ghostStatus.checking = false; }
}

export const GHOST_ORIGIN = 'https://sukgicalm-lang.github.io/ghost-valheim-vault';
export const GHOST_LEGACY_ORIGIN = 'https://user.tail054318.ts.net';
export const GHOST_REFRESH_INTERVAL = 30_000;
export function ghostDownloadUrl(version: string): string {
    if (!/^\d+\.\d+\.\d+$/.test(version)) throw new Error('Invalid Ghost version');
    return `https://github.com/sukgicalm-lang/ghost-valheim-vault/releases/download/suite-${version}/Ghost-GhostValheimSuite-${version}.zip`;
}
export function isTrustedGhostDownloadUrl(url: string, version: string, packageName = GHOST_PACKAGE): boolean {
    if (packageName === GHOST_SMELTER_PACKAGE) return url === ghostSmelterDownloadUrl(version);
    if (packageName !== GHOST_PACKAGE) return false;
    return url === ghostDownloadUrl(version) || url === `${GHOST_LEGACY_ORIGIN}/downloads/Ghost-GhostValheimSuite-${version}.zip`;
}
export const GHOST_PACKAGE = 'Ghost-GhostValheimSuite';
export const GHOST_SMELTER_PACKAGE = 'Ghost-GhostSmelterControl';
export const GHOST_PACKAGES = [GHOST_PACKAGE, GHOST_SMELTER_PACKAGE];
export function isGhostPackage(name: string): boolean { return GHOST_PACKAGES.includes(name); }
export function ghostSmelterDownloadUrl(version: string): string {
    if (!/^\d+\.\d+\.\d+$/.test(version)) throw new Error('Invalid Ghost version');
    return `https://github.com/sukgicalm-lang/ghost-valheim-vault/releases/download/smelter-${version}/Ghost-GhostSmelterControl-${version}.zip`;
}
export const GHOST_SCHEME = 'ghostvault';
export const GHOST_DEPENDENCIES = [
    'denikson-BepInExPack_Valheim-5.4.2351',
    'ValheimModding-JsonDotNET-13.0.4',
    'shudnal-ConfigurationManager-1.1.25',
];
export interface GhostRelease {
    version: string;
    date: string;
    file: string;
    bytes: number;
    sha256: string;
    dependencies?: string[];
    notes?: string;
}
export function isGhostGame(community: string): boolean {
    return community.toLowerCase() === 'valheim';
}
export function parseGhostProtocol(input: string): string {
    return parseGhostProtocolTarget(input).version;
}
export function parseGhostProtocolTarget(input: string): { packageName: string; version: string } {
    const match = /^ghostvault:\/\/v1\/install\/(Ghost-GhostValheimSuite|Ghost-GhostSmelterControl)\/(latest|\d+\.\d+\.\d+)\/?$/.exec(input);
    if (!match) throw new Error('올바르지 않은 GHOST 설치 링크입니다.');
    return { packageName: match[1]!, version: match[2]! };
}
export function validateGhostRelease(value: unknown): GhostRelease {
    if (!value || typeof value !== 'object') throw new Error('GHOST 배포 정보가 없습니다.');
    const r = value as GhostRelease;
    if (typeof r.version !== 'string' || !/^\d+\.\d+\.\d+$/.test(r.version)) throw new Error('배포 버전이 올바르지 않습니다.');
    if (typeof r.date !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(r.date) || !Number.isFinite(Date.parse(r.date))) throw new Error('배포 날짜가 올바르지 않습니다.');
    if (typeof r.file !== 'string' || !/^downloads\/[A-Za-z0-9_.-]+\.zip$/.test(r.file)) throw new Error('다운로드 경로가 올바르지 않습니다.');
    if (!Number.isSafeInteger(r.bytes) || r.bytes <= 0 || r.bytes > 512 * 1024 * 1024) throw new Error('배포 파일 크기가 올바르지 않습니다.');
    if (typeof r.sha256 !== 'string' || !/^[a-f0-9]{64}$/.test(r.sha256)) throw new Error('배포 파일 검증 정보가 올바르지 않습니다.');
    if (r.dependencies && (!Array.isArray(r.dependencies) || r.dependencies.some(x => typeof x !== 'string' || !/^[A-Za-z0-9_]+-[A-Za-z0-9_]+-\d+\.\d+\.\d+$/.test(x)))) throw new Error('선행 모드 정보가 올바르지 않습니다.');
    return { ...r, dependencies: [...(r.dependencies || GHOST_DEPENDENCIES)] };
}
export function compareGhostVersions(a: string, b: string): number {
    const aa = a.split('.').map(Number), bb = b.split('.').map(Number);
    for (let i = 0; i < 3; i++) if (aa[i] !== bb[i]) return aa[i]! - bb[i]!;
    return 0;
}
export function normalizeGhostCatalog(input: unknown): GhostRelease[] {
    if (!Array.isArray(input) || !input.length || input.length > 100) throw new Error('배포 목록이 올바르지 않습니다.');
    const releases = input.map(validateGhostRelease).sort((a, b) => compareGhostVersions(b.version, a.version));
    if (new Set(releases.map(r => r.version)).size !== releases.length) throw new Error('중복 버전이 있습니다.');
    return releases;
}
export function ghostPackageFromReleases(input: unknown, packageName = GHOST_PACKAGE) {
    if (!isGhostPackage(packageName)) throw new Error('Unknown Ghost package');
    const releases = normalizeGhostCatalog(input);
    const smelter = packageName === GHOST_SMELTER_PACKAGE;
    if (smelter && releases.some(r => r.file !== `downloads/Ghost-GhostSmelterControl-${r.version}.zip`)) throw new Error('Invalid smelter package path');
    const name = smelter ? 'GhostSmelterControl' : 'GhostValheimSuite';
    return {
        name, full_name: packageName, owner: 'Ghost',
        uuid4: smelter ? '32a252a5-f240-42c8-aee8-4f495758f1b8' : 'd049a4aa-6c00-4d36-93ee-f9802d149cf1', package_url: GHOST_ORIGIN + '/',
        date_created: releases[releases.length - 1]!.date + 'T00:00:00Z',
        date_updated: releases[0]!.date + 'T00:00:00Z',
        rating_score: 0, is_pinned: true, is_deprecated: false, has_nsfw_content: false,
        donation_link: null, categories: ['GHOST'],
        versions: releases.map(r => ({
            name, full_name: `${packageName}-${r.version}`,
            version_number: r.version, uuid4: smelter ? `ghost-smelter-${r.version}` : `ghost-${r.version}`, description: r.notes || (smelter ? 'Ghost 제련 제어 · 1초 생산 · 원료/연료 100개' : 'Ghost 통합팩 · 장비 선택 교환, 숙련도 XP 2배, 생활 편의 모드'),
            icon: GHOST_ORIGIN + '/assets/pack-icon.png', dependencies: r.dependencies!,
            downloads: 0, download_url: smelter ? ghostSmelterDownloadUrl(r.version) : ghostDownloadUrl(r.version),
            website_url: GHOST_ORIGIN + '/', date_created: r.date + 'T00:00:00Z',
            file_size: r.bytes, is_active: true, ghost_sha256: r.sha256,
        })),
    };
}

import {reactive} from 'vue';
import type Game from '../model/game/Game';
import type {ImmutableProfile} from '../model/Profile';
import type ManifestV2 from '../model/ManifestV2';
import R2Error,{throwForR2Error} from '../model/errors/R2Error';
import ProfileModList from '../r2mm/mods/ProfileModList';
import ProfileInstallerProvider from '../providers/ror2/installing/ProfileInstallerProvider';
import FsProvider from '../providers/generic/file/FsProvider';
import {getStore} from '../providers/generic/store/StoreProvider';
import * as Db from '../r2mm/manager/PackageDexieStore';
import {loadGhostSetup,seedGhostSetupCatalog,resolveGhostSetupCombos} from './GhostSetupCatalog';
import {planGhostSetup,orderSetupPackages,type SetupPackage} from './GhostSetupCore';
import {syncGhostRepository} from './GhostRepository';
import {backupGhostProfile} from './GhostInstallSafety';
import {InstallMode} from '../utils/DependencyUtils';
import {GHOST_PACKAGE,GHOST_SMELTER_PACKAGE,isGhostGame,isGhostPackage,compareGhostVersions} from './GhostRepositoryCore';
type Phase='checking'|'installing'|'waiting'|'error'|'complete';
export interface RequiredSetupState {phase:Phase;message:string;count:number;}
export const ghostRequiredStates=reactive(new Map<string,RequiredSetupState>());
const active=new Map<string,Promise<boolean>>(),retryAfter=new Map<string,number>();
export function requiredSetupKey(game:Game,profile:ImmutableProfile){return game.internalFolderName+':'+profile.getProfilePath();}
export async function hasSetupPayload(profile:ImmutableProfile,p:SetupPackage,allowDisabled=false):Promise<boolean>{
    const fs=FsProvider.instance;
    if(p.name==='denikson-BepInExPack_Valheim')return fs.exists(profile.joinToProfilePath('BepInEx','core','BepInEx.dll'));
    const expected=p.name===GHOST_SMELTER_PACKAGE?'ghostsmeltercontrol.dll':undefined;
    async function walk(dir:string,depth:number):Promise<boolean>{
        if(depth>8 || !await fs.exists(dir))return false;
        for(const name of await fs.readdir(dir)){
            const file=dir+'/'+name,stat=await fs.lstat(file),plain=name.toLowerCase().replace(allowDisabled?/\.old$/:/$^/,'');
            if(stat.isFile() && (expected?plain===expected:plain.endsWith('.dll')))return true;
            if(stat.isDirectory() && await walk(file,depth+1))return true;
        }return false;
    }
    for(const folder of ['plugins','patchers'])if(await walk(profile.joinToProfilePath('BepInEx',folder,p.name),0))return true;
    return false;
}
function snapshots(mods:ManifestV2[]){return mods.map(m=>({name:m.getName(),version:m.getVersionNumber().toString(),enabled:m.isEnabled()}));}
export async function ensureGhostRequiredSetup(game:Game,profile:ImmutableProfile,store=getStore<any>(),force=false):Promise<boolean>{
    if(!isGhostGame(game.internalFolderName))return true;
    const key=requiredSetupKey(game,profile),pending=active.get(key);if(pending)return pending;
    const current=()=>store.state.activeGame.internalFolderName===game.internalFolderName && store.getters['profile/activeProfile'].getProfilePath()===profile.getProfilePath();
    let count=0;
    const set=(phase:Phase,message:string)=>ghostRequiredStates.set(key,{phase,message,count});
    async function guard(installing=false){
        if(!current())throw new Error('프로필이 변경되어 필수 모드 준비를 중단했습니다.');
        if(!await window.app.ensureGhostExclusive())throw new Error('일반 r2modman을 종료하면 필수 모드를 자동으로 준비합니다.');
        if(await window.app.isGhostGameRunning())throw new Error('게임을 종료하면 필수 모드를 자동으로 준비합니다.');
        if((store.getters['download/activeDownloadCount']||0)>(installing?1:0))throw new Error('다른 설치가 끝나면 필수 모드를 자동으로 준비합니다.');
        if(!current())throw new Error('프로필이 변경되어 필수 모드 준비를 중단했습니다.');
    }
    const work=(async()=>{
        try{
            if(!force && Date.now()<(retryAfter.get(key)||0))return false;
            set('checking','전체 필수 모드 구성을 확인하고 있습니다.');
            const setup=await loadGhostSetup(profile);count=setup.packages.length;
            try{await syncGhostRepository(game);}catch{/* Validated cached/bundled metadata is used below. */}
            await seedGhostSetupCatalog(game,setup);
            const required=setup.packages.map(p=>({...p}));
            // Ghost-owned modules follow their latest verified public release.
            for(const p of required.filter(p=>isGhostPackage(p.name))){
                const newest=(await Db.getCombosByDependencyStrings(game,[p.name+'-'+p.version],true))[0];
                if(newest && compareGhostVersions(newest.getVersion().getVersionNumber().toString(),p.version)>0)p.version=newest.getVersion().getVersionNumber().toString();
            }
            let mods=throwForR2Error(await ProfileModList.getModList(profile));
            // Do not downgrade an already installed newer version during repair.
            for(const p of required){const installed=mods.find(m=>m.getName()===p.name);if(installed&&compareGhostVersions(installed.getVersionNumber().toString(),p.version)>0)p.version=installed.getVersionNumber().toString();}
            async function plan(){
                const payloads=new Map<string,boolean>();
                for(const p of required){const m=mods.find(m=>m.getName()===p.name);payloads.set(p.name,!!m&&await hasSetupPayload(profile,p,!m.isEnabled()));}
                return planGhostSetup(required,snapshots(mods),payloads);
            }
            let todo=await plan();
            if(!todo.install.length&&!todo.enable.length){set('complete',`필수 모드 ${count}개 준비 완료 · Start modded로 실행하세요.`);return true;}
            try{await guard();}catch(e){set('waiting',(e as Error).message);return false;}
            if(mods.some(m=>m.isEnabled() && /frizz/i.test(m.getName()) && /smelter.?control/i.test(m.getName())))throw new Error('기존 FrizzQOL Smelter Control을 제거하면 필수 제련 모드를 자동으로 설치합니다.');
            if(todo.enable.length){
                await ProfileModList.requestLock(async()=>{
                    await guard();
                    const all=await resolveGhostSetupCombos(game,setup,required);
                    await backupGhostProfile(all,profile,true);
                    mods=throwForR2Error(await ProfileModList.getModList(profile));
                    for(const p of todo.enable){const m=mods.find(m=>m.getName()===p.name);if(m&&!m.isEnabled()){await guard();throwForR2Error(await ProfileInstallerProvider.instance.enableMod(m,profile));m.enable();}}
                    throwForR2Error(await ProfileModList.saveModList(profile,mods));
                });
                todo=await plan();
            }
            if(todo.install.length){
                await guard();
                const combos=await resolveGhostSetupCombos(game,setup,required);
                if(combos.length!==required.length)throw new Error('필수 모드 일부의 배포 정보를 찾지 못했습니다. 잠시 후 자동으로 다시 시도합니다.');
                for(const c of combos)for(const dep of c.getVersion().getDependencies()){
                    const i=dep.lastIndexOf('-'),name=dep.slice(0,i),version=dep.slice(i+1);
                    const planned=required.find(p=>p.name===name),installed=mods.find(m=>m.getName()===name);
                    if((!planned||compareGhostVersions(planned.version,version)<0)&&(!installed||!installed.isEnabled()||compareGhostVersions(installed.getVersionNumber().toString(),version)<0))throw new Error('필수 선행 모드의 배포 기준을 확인해야 합니다: '+dep);
                }
                const needs=new Set(todo.install.map(p=>p.name));
                // Resolve dependencies against the entire pinned baseline, then download
                // only missing/outdated packages. Never replace a current suite just
                // because a small component is missing.
                const ordered=orderSetupPackages(combos.map(c=>({name:c.getMod().getFullName(),dependencies:c.getVersion().getDependencies(),combo:c}))).filter(x=>needs.has(x.name)).map(x=>x.combo);
                set('installing',`필수 모드 ${count}개 중 ${ordered.length}개를 자동 설치·업데이트하고 있습니다.`);
                await store.dispatch('download/downloadAndInstallCombos',{combos:ordered,game,profile,installMode:InstallMode.INSTALL_SPECIFIC,hideModal:true,
                    resolvedCombos:ordered,throwOnError:true,reportError:false,beforeInstall:()=>guard(true),forceReinstall:todo.install.filter(p=>mods.some(m=>m.getName()===p.name)).map(p=>p.name),backupAll:true});
            }
            mods=throwForR2Error(await ProfileModList.getModList(profile));todo=await plan();
            if(todo.install.length||todo.enable.length)throw new Error('필수 모드 준비가 완료되지 않았습니다. 다시 시도를 누르세요.');
            if(current())await store.dispatch('profile/tryLoadModListFromDisk');
            retryAfter.delete(key);set('complete',`필수 모드 ${count}개 준비 완료 · Start modded로 실행하세요.`);return true;
        }catch(error){retryAfter.set(key,Date.now()+30000);set('error',error instanceof Error?error.message:'필수 모드를 준비하지 못했습니다. 다시 시도해 주세요.');return false;}
    })();active.set(key,work);try{return await work;}finally{if(active.get(key)===work)active.delete(key);}
}
export async function requireGhostSetupBeforeLaunch(game:Game,profile:ImmutableProfile){
    if(!await ensureGhostRequiredSetup(game,profile,getStore<any>(),true))throw new R2Error('필수 모드 준비 중',ghostRequiredStates.get(requiredSetupKey(game,profile))?.message||'필수 모드가 준비된 뒤 게임을 실행하세요.');
}

import axios from 'axios';
import bundled from './GhostSetupBundle.json';
import {validateGhostSetup,setupCdnUrl,type GhostSetup} from './GhostSetupCore';
import {GHOST_ORIGIN,GHOST_PACKAGE,GHOST_SMELTER_PACKAGE,ghostPackageFromReleases,compareGhostVersions} from './GhostRepositoryCore';
import * as Db from '../r2mm/manager/PackageDexieStore';
import type Game from '../model/game/Game';
import ThunderstoreCombo from '../model/ThunderstoreCombo';
import ThunderstoreMod from '../model/ThunderstoreMod';
import ThunderstoreVersion from '../model/ThunderstoreVersion';
import FsProvider from '../providers/generic/file/FsProvider';
import type {ImmutableProfile} from '../model/Profile';
let current=validateGhostSetup(bundled.setup),lastCheck=0,pending:Promise<GhostSetup>|undefined;
export async function loadGhostSetup(profile:ImmutableProfile):Promise<GhostSetup>{
    if(pending)return pending;
    if(Date.now()-lastCheck<25000)return current;
    pending=(async()=>{
        const fs=FsProvider.instance,cache=profile.joinToProfilePath('GhostSetup','setup-release.json');
        try{const saved=validateGhostSetup(JSON.parse((await fs.readFile(cache)).toString()));if(saved.revision>current.revision)current=saved;}catch{/* First run or invalid cached metadata. */}
        try{
            const r=await axios.get(GHOST_ORIGIN+'/setup-release.json',{timeout:8000,params:{ghost_check:Date.now()},headers:{'Cache-Control':'no-cache'}});
            const fresh=validateGhostSetup(r.data);if(fresh.revision<current.revision)throw new Error('필수 모드 배포 기준이 이전 버전입니다.');
            if(fresh.revision===current.revision && JSON.stringify(fresh)!==JSON.stringify(current))throw new Error('같은 필수 구성 버전의 내용이 다릅니다.');
            current=fresh;await fs.mkdirs(profile.joinToProfilePath('GhostSetup'));await fs.writeFile(cache,JSON.stringify(current));
        }catch{/* Validated bundled/cached baseline remains usable, including offline play. */}
        lastCheck=Date.now();return current;
    })();
    try{return await pending;}finally{pending=undefined;}
}
export async function seedGhostSetupCatalog(game:Game,setup:GhostSetup){
    for(const p of setup.packages){
        const cached=await Db.getPackageFromDatabase(game.internalFolderName,p.name).catch(()=>undefined);
        if(p.name===GHOST_PACKAGE || p.name===GHOST_SMELTER_PACKAGE){
            if(!cached)await Db.upsertPackageListChunk(game.internalFolderName,[ghostPackageFromReleases([p.name===GHOST_PACKAGE?bundled.suite:bundled.smelter],p.name)]);
            continue;
        }
        const [owner,name]=p.name.split('-') as [string,string];
        const version={name,full_name:p.name+'-'+p.version,version_number:p.version,uuid4:'ghost-setup-'+p.name+'-'+p.version,
            dependencies:p.dependencies!,description:p.description||name,icon:GHOST_ORIGIN+'/assets/pack-icon.png',downloads:0,
            download_url:setupCdnUrl(p),website_url:`https://thunderstore.io/c/valheim/p/${owner}/${name}/`,date_created:setup.date+'T00:00:00Z',file_size:p.bytes!,is_active:true,ghost_setup_sha256:p.sha256!};
        const versions=[version,...(cached?.versions||[]).filter(v=>v.version_number!==p.version)].sort((a,b)=>compareGhostVersions(b.version_number,a.version_number));
        await Db.upsertPackageListChunk(game.internalFolderName,[{...cached,name,full_name:p.name,owner,uuid4:cached?.uuid4||'ghost-setup-'+p.name,
            package_url:version.website_url,date_created:cached?.date_created||version.date_created,date_updated:cached?.date_updated||version.date_created,
            rating_score:cached?.rating_score||0,is_pinned:cached?.is_pinned||false,is_deprecated:false,has_nsfw_content:false,donation_link:null,categories:cached?.categories||[],versions}]);
    }
}

// The community index can refresh concurrently. Construct pinned third-party
// download versions from the verified setup metadata so that refreshes cannot
// erase the CDN URL/hash between planning and downloading.
export async function resolveGhostSetupCombos(game:Game,setup:GhostSetup,required:GhostSetup['packages']):Promise<ThunderstoreCombo[]>{
    const result:ThunderstoreCombo[]=[];
    for(const p of required){
        const baseline=setup.packages.find(x=>x.name===p.name);
        if(p.name!==GHOST_PACKAGE&&p.name!==GHOST_SMELTER_PACKAGE&&baseline?.version===p.version){
            const [owner,name]=p.name.split('-') as [string,string],row=baseline;
            const version={name,full_name:p.name+'-'+p.version,version_number:p.version,dependencies:row.dependencies!,
                description:row.description||name,icon:GHOST_ORIGIN+'/assets/pack-icon.png',downloads:0,download_url:setupCdnUrl(row),
                website_url:`https://thunderstore.io/c/valheim/p/${owner}/${name}/`,date_created:setup.date+'T00:00:00Z',file_size:row.bytes!,is_active:true,ghost_setup_sha256:row.sha256!};
            const combo=new ThunderstoreCombo();
            combo.setMod(ThunderstoreMod.parseFromThunderstoreData({name,owner,full_name:p.name,package_url:version.website_url,
                date_created:version.date_created,date_updated:version.date_created,rating_score:0,is_pinned:false,is_deprecated:false,has_nsfw_content:false,donation_link:null,categories:[],versions:[version]}));
            combo.setVersion(ThunderstoreVersion.parseFromThunderstoreData(version));result.push(combo);
        }else result.push(...await Db.getCombosByDependencyStrings(game,[p.name+'-'+p.version]));
    }return result;
}

import {compareGhostVersions, GHOST_PACKAGE, GHOST_SMELTER_PACKAGE} from './GhostRepositoryCore';
export interface SetupPackage {name:string;version:string;bytes?:number;sha256?:string;dependencies?:string[];description?:string;}
export interface GhostSetup {schema:1;revision:number;date:string;packages:SetupPackage[];}
export const setupCdnUrl=(p:SetupPackage)=>`https://gcdn.thunderstore.io/live/repository/packages/${p.name}-${p.version}.zip`;
const ghosts=[GHOST_PACKAGE,GHOST_SMELTER_PACKAGE];
export function validateGhostSetup(input:unknown):GhostSetup {
    const x=input as GhostSetup;
    if(!x || x.schema!==1 || !Number.isSafeInteger(x.revision) || x.revision<1 || !/^\d{4}-\d{2}-\d{2}$/.test(x.date)
        || !Array.isArray(x.packages) || x.packages.length<2 || x.packages.length>100)throw new Error('필수 모드 배포 기준이 올바르지 않습니다.');
    const names=new Set<string>();
    for(const p of x.packages){
        if(!p || typeof p.name!=='string' || !/^[A-Za-z0-9_]+-[A-Za-z0-9_]+$/.test(p.name) || !/^\d+\.\d+\.\d+$/.test(p.version) || names.has(p.name))throw new Error('필수 모드 이름·버전이 올바르지 않습니다.');
        names.add(p.name);
        if(ghosts.includes(p.name))continue;
        if(p.name.startsWith('Ghost-') || !Number.isSafeInteger(p.bytes) || p.bytes!<=0 || p.bytes!>512*1024*1024 || !/^[a-f0-9]{64}$/.test(p.sha256||'')
            || !Array.isArray(p.dependencies) || p.dependencies.some(d=>typeof d!=='string'|| !/^[A-Za-z0-9_]+-[A-Za-z0-9_]+-\d+\.\d+\.\d+$/.test(d)))throw new Error('필수 모드 검증 정보가 올바르지 않습니다.');
    }
    if(ghosts.some(p=>!names.has(p)))throw new Error('Ghost 기본 모드가 빠져 있습니다.');
    for(const p of x.packages)for(const dep of p.dependencies||[]){
        const i=dep.lastIndexOf('-'),name=dep.slice(0,i),version=dep.slice(i+1),target=x.packages.find(p=>p.name===name);
        if(!target || compareGhostVersions(target.version,version)<0)throw new Error('필수 선행 모드가 배포 기준에 없습니다: '+dep);
    }
    return JSON.parse(JSON.stringify(x));
}
export interface InstalledSetupMod {name:string;version:string;enabled:boolean;}
export function planGhostSetup(required:SetupPackage[],installed:InstalledSetupMod[],payloads:Map<string,boolean>){
    const install=required.filter(p=>{const m=installed.find(m=>m.name===p.name);return !m || compareGhostVersions(m.version,p.version)<0 || !payloads.get(p.name);});
    const enable=required.filter(p=>installed.some(m=>m.name===p.name&&!m.enabled));
    return {install,enable};
}
export function orderSetupPackages<T extends {name:string;dependencies?:string[]}>(packages:T[]):T[]{
    const result:T[]=[],visiting=new Set<string>(),done=new Set<string>();
    function visit(p:T){if(done.has(p.name))return;if(visiting.has(p.name))throw new Error('필수 모드의 선행 관계가 순환합니다.');visiting.add(p.name);
        for(const d of p.dependencies||[]){const dep=packages.find(x=>d.startsWith(x.name+'-'));if(dep)visit(dep);}
        visiting.delete(p.name);done.add(p.name);result.push(p);}
    packages.forEach(visit);return result;
}

import { reactive } from 'vue';
import axios from 'axios';
import Game from '../model/game/Game';
import * as Db from '../r2mm/manager/PackageDexieStore';
import { GHOST_ORIGIN, GHOST_SMELTER_PACKAGE, normalizeGhostCatalog, validateGhostRelease,
    compareGhostVersions, ghostPackageFromReleases } from './GhostRepositoryCore';

export const ghostSmelterStatus = reactive({ error: '', latest: '', checking: false });

// Runs alongside the original suite query. A missing/addon-only feed must never
// replace, block, or roll back the suite catalog.
export async function syncGhostSmelterRepository(game: Game): Promise<void> {
    ghostSmelterStatus.checking = true;
    try {
        const options = { timeout: 8000, params: { ghost_check: Date.now().toString(36) + Math.random().toString(36).slice(2) },
            headers: { 'Cache-Control': 'no-cache, no-store, max-age=0', Pragma: 'no-cache' } };
        const [latestResult, catalogResult] = await Promise.allSettled([
            axios.get(GHOST_ORIGIN + '/smelter-release.json', options),
            axios.get(GHOST_ORIGIN + '/smelter-releases.json', options),
        ]);
        let checked = catalogResult.status === 'fulfilled' ? normalizeGhostCatalog(catalogResult.value.data) : [];
        const latest = latestResult.status === 'fulfilled' ? validateGhostRelease(latestResult.value.data) : undefined;
        if (latest) {
            const same = checked.find(r => r.version === latest.version);
            if (same && (same.sha256 !== latest.sha256 || same.bytes !== latest.bytes)) throw new Error('Ghost smelter feed conflict');
            checked = normalizeGhostCatalog([...checked.filter(r => r.version !== latest.version), latest]);
        }
        if (!checked.length) throw new Error('Ghost smelter feed unavailable');
        const cached = await Db.getPackageFromDatabase(game.internalFolderName, GHOST_SMELTER_PACKAGE).catch(() => undefined);
        if (cached && catalogResult.status === 'rejected') {
            const older = cached.versions.map((v: any) => validateGhostRelease({ version: v.version_number,
                date: v.date_created.slice(0, 10), file: `downloads/Ghost-GhostSmelterControl-${v.version_number}.zip`,
                bytes: v.file_size, sha256: v.ghost_sha256, notes: v.description, dependencies: v.dependencies }));
            checked = normalizeGhostCatalog([...checked, ...older.filter(r => !checked.some(n => n.version === r.version))].slice(0, 100));
        }
        if (cached?.versions.length && compareGhostVersions(cached.versions[0]!.version_number, checked[0]!.version) > 0)
            throw new Error('Smelter feed is older than the saved catalog');
        await Db.upsertPackageListChunk(game.internalFolderName, [ghostPackageFromReleases(checked, GHOST_SMELTER_PACKAGE)]);
        ghostSmelterStatus.latest = checked[0]!.version;
        ghostSmelterStatus.error = latest ? '' : '제련 모드의 최신 배포 조회에 실패하여 저장된 목록을 사용합니다.';
    } catch {
        ghostSmelterStatus.error = '제련 모드 배포에 연결하지 못했습니다. 저장된 버전은 유지합니다.';
    } finally { ghostSmelterStatus.checking = false; }
}

import Game from './game/Game';
import ThunderstoreMod from './ThunderstoreMod';
import R2Error from './errors/R2Error';
import ThunderstoreVersion from './ThunderstoreVersion';
import * as PackageDb from '../r2mm/manager/PackageDexieStore';
import { isGhostGame, parseGhostProtocolTarget } from '../ghost/GhostRepositoryCore';
import { syncGhostRepository } from '../ghost/GhostRepository';

export default class ThunderstoreCombo {

    private mod: ThunderstoreMod = new ThunderstoreMod();
    private version: ThunderstoreVersion = new ThunderstoreVersion();

    public static async fromProtocol(protocol: string, game: Game): Promise<ThunderstoreCombo | R2Error> {
        if (protocol.startsWith('ghostvault:')) {
            try {
                const { packageName, version } = parseGhostProtocolTarget(protocol);
                if (!isGhostGame(game.internalFolderName)) throw new Error('Valheim과 설치할 프로필을 먼저 선택하세요.');
                await syncGhostRepository(game, true);
                const found = await PackageDb.getCombosByDependencyStrings(game, [`${packageName}-${version === 'latest' ? '0.0.0' : version}`], version === 'latest');
                if (!found.length) throw new Error('요청한 Ghost 배포 버전을 찾지 못했습니다.');
                return found[0]!;
            } catch (error) { return R2Error.fromThrownValue(error, 'Ghost 설치 링크를 처리하지 못했습니다.'); }
        }
        // Remove protocol information and trailing slash, leaving the package version information.
        const reducedProtocol = protocol
            .replace(new RegExp('ror2mm://v1/install/([a-zA-Z0-9]+\.)?thunderstore\.io/'), '')
            .replace(new RegExp('\/$'), '');
        const dependencyString = reducedProtocol.split('/').join('-');
        const foundMod = await PackageDb.getCombosByDependencyStrings(game, [dependencyString]);

        if (!foundMod.length) {
            return new R2Error(
                'Mod does not exist',
                `Unable to resolve ${dependencyString} to a suitable Thunderstore mod or version`,
                'Relaunch the manager to update the mod list. Ensure the correct game and profile is selected before opening the link.'
            );
        }

        return foundMod[0]!;
    }

    public getMod(): ThunderstoreMod {
        return this.mod;
    }

    public setMod(mod: ThunderstoreMod) {
        this.mod = mod;
    }

    public getVersion(): ThunderstoreVersion {
        return this.version;
    }

    public setVersion(version: ThunderstoreVersion) {
        this.version = version;
    }

    public getDependencyString(): string {
        return `${this.mod.getFullName()}-${this.version.getVersionNumber().toString()}`;
    }

    public getUserFriendlyString(): string {
        return `${this.mod.getName()} (${this.version.getVersionNumber().toString()})`;
    }
}

import VersionNumber from './VersionNumber';
import CdnProvider from '../providers/generic/connection/CdnProvider';

export default class ThunderstoreVersion  {

    private name: string = '';
    private versionNumber: VersionNumber = new VersionNumber('0.0.0');
    private dependencies: string[] = [];
    private fullName: string = '';
    private description: string = ''
    private icon: string = ''
    private enabled: boolean = true;
    private downloads: number = 0;
    private downloadUrl: string = '';
    private fileSize: number = 0;
    private dateCreated: string = '';
    private ghostSha256: string = '';
    private ghostSetupSha256: string = '';

    public static parseFromThunderstoreData(data: any): ThunderstoreVersion {
        const version = new ThunderstoreVersion();
        version.make(data);
        return version;
    }

    public make(version: any): ThunderstoreVersion {
        this.setName(version.name);
        this.setFullName(version.full_name);
        this.setDependencies(version.dependencies);
        this.setDescription(version.description);
        this.setVersionNumber(new VersionNumber(version.version_number));
        this.setIcon(version.icon);
        this.setDownloadCount(version.downloads);
        this.setDownloadUrl(version.download_url);
        this.ghostSha256 = typeof version.ghost_sha256 === 'string' ? version.ghost_sha256 : '';
        this.ghostSetupSha256 = typeof version.ghost_setup_sha256==='string'?version.ghost_setup_sha256:'';
        this.setFileSize(version.file_size);
        this.setFileSize(version.file_size);
        this.setDateCreated(version.date_created);
        return this;
    }

    public getName(): string {
        return this.name;
    }

    public setName(name: string) {
        this.name = name;
    }

    public getVersionNumber(): VersionNumber {
        return this.versionNumber;
    }

    public setVersionNumber(versionNumber: VersionNumber) {
        this.versionNumber = versionNumber;
    }

    public getDependencies(): string[] {
        return this.dependencies;
    }

    public setDependencies(dependencies: string[]) {
        this.dependencies = dependencies;
    }

    public getFullName(): string {
        return this.fullName;
    }

    public setFullName(name: string) {
        this.fullName = name;
    }

    public getDescription(): string {
        return this.description;
    }

    public setDescription(description: string) {
        this.description = description;
    }

    public getIcon(): string {
        return this.icon;
    }

    public setIcon(icon: string) {
        this.icon = icon;
    }

    public isEnabled(): boolean {
        return this.enabled;
    }

    public enable() {
        this.enabled = true;
    }

    public disable() {
        this.enabled = false;
    }

    public getDownloadCount(): number {
        return this.downloads;
    }

    public setDownloadCount(downloads: number) {
        this.downloads = downloads;
    }

    public getDownloadUrl(): string {
        if (this.ghostSha256 || this.ghostSetupSha256) return this.downloadUrl;
        return CdnProvider.addCdnQueryParameter(this.downloadUrl);
    }

    public getGhostSha256(): string { return this.ghostSha256; }
    public getGhostSetupSha256(): string { return this.ghostSetupSha256; }

    public setDownloadUrl(url: string) {
        this.downloadUrl = url;
    }

    public setFileSize(size: number) {
        this.fileSize = size;
    }

    public getFileSize(): number {
        return this.fileSize;
    }

    public setDateCreated(dateCreated: string) {
        this.dateCreated = dateCreated;
    }

    public getDateCreated(): Date | undefined {
        try {
            return new Date(this.dateCreated);
        } catch (e) {
            return undefined;
        }
    }
}

import Dexie, { Table } from 'dexie';

import { DexiePackage, DexieSummary, fetchPackagesByCommunityPackagePairs } from './PackageDexieStoreMockables';
import Game from '../../model/game/Game';
import ThunderstoreCombo from '../../model/ThunderstoreCombo';
import ThunderstoreMod from '../../model/ThunderstoreMod';
import ThunderstoreVersion from '../../model/ThunderstoreVersion';
import { splitToNameAndVersion } from '../../utils/DependencyUtils';
import { GHOST_PACKAGE, GHOST_PACKAGES, isGhostGame } from '../../ghost/GhostRepositoryCore';



// For keeping track of seen package list index files so we can
// skip processing chunks if there's no changes.
interface IndexChunkHash {
    community: string;
    hash: string;
    date_updated: Date;
}

class PackageDexieStore extends Dexie {
    packages!: Table<DexiePackage, [string, string]>;
    indexHashes!: Table<IndexChunkHash, string>;
    summaries!: Table<DexieSummary, [string, string]>;

    constructor() {
        super('tsPackages');

        this.version(1).stores({
            packages: '[community+full_name], [community+date_fetched]'
        });
        this.version(2).stores({
            indexHashes: '&community, [community+hash]'
        });
        this.version(3).stores({
            summaries: '[community+full_name]',
            packages: '[community+full_name]'
        });
    }
}

const db = new PackageDexieStore();

function toSummary(community: string, pkg: any): DexieSummary {
    return {
        community,
        full_name: pkg.full_name,
        name: pkg.name,
        owner: pkg.owner,
        package_url: pkg.package_url,
        date_created: pkg.date_created,
        date_updated: pkg.date_updated,
        categories: pkg.categories,
        rating_score: pkg.rating_score,
        is_pinned: pkg.is_pinned,
        is_deprecated: pkg.is_deprecated,
        has_nsfw_content: pkg.has_nsfw_content,
        donation_link: pkg.donation_link,
        total_downloads: pkg.versions.reduce((x: number, v: {downloads: number}) => x + v.downloads, 0),
        latest_version_number: pkg.versions[0].version_number,
        latest_description: pkg.versions[0].description,
        latest_icon: pkg.versions[0].icon,
    };
}

async function rebuildSummaries(community: string): Promise<DexieSummary[]> {
    return await db.transaction('rw', db.packages, db.summaries, async () => {
        const pkgs = await db.packages.where({community}).toArray();
        const summaries = pkgs.map((p) => toSummary(community, p));
        await db.summaries.bulkPut(summaries);
        return summaries;
    });
}

export async function getPackagesAsThunderstoreMods(community: string) {
    let summaries = await db.summaries.where({community}).toArray();

    if (summaries.length === 0) {
        summaries = await rebuildSummaries(community);
    }

    return summaries.map(ThunderstoreMod.parseFromSummary)
                    .sort(ThunderstoreMod.defaultOrderComparer);
}

export async function getPackagesByNames(community: string, packageNames: string[]) {
    const keys = packageNames.map((p): [string, string] => [community, p]);

    // Dexie's anyOfIgnoreCase doesn't support compound indexes.
    const packages = await db.packages.where('[community+full_name]').anyOf(keys).toArray();
    return packages.map(ThunderstoreMod.parseFromThunderstoreData);
}

export async function getPackageVersionNumbers(community: string, packageName: string) {
    const pkg = await getPackageFromDatabase(community, packageName);
    return pkg.versions.map((v) => v.version_number);
}

export async function getPackageVersionNumbersBatch(community: string, packageNames: string[]): Promise<Map<string, string[]>> {
    const keys = packageNames.map((p): [string, string] => [community, p]);
    const packages = await db.packages.where('[community+full_name]').anyOf(keys).toArray();
    return new Map(packages.map(pkg => [pkg.full_name, pkg.versions.map(v => v.version_number)]));
}

export async function getPackageCount(community: string) {
    return await db.packages.where({community}).count();
}

/**
 * @param game Game (community) which package listings should be used in the lookup.
 * @param dependencies Lookup targets as Thunderstore dependency strings.
 * @param useLatestVersion Ignore the version number in dependencyString and return the latest known version.
 * @returns ThunderstoreCombo[], silently omitting unknown packages and versions.
 */
export async function getCombosByDependencyStrings(
    game: Game,
    dependencyStrings: string[],
    useLatestVersion=false
): Promise<ThunderstoreCombo[]> {
    const community = game.internalFolderName;
    const split = dependencyStrings.map(splitToNameAndVersion);
    const keys = split.map((d): [string, string] => [community, d[0]]);

    const packages = await fetchPackagesByCommunityPackagePairs(db, keys);
    const versionMap = Object.fromEntries(split);
    const modOrderMap = new Map(split.map(([name, _ver], i) => [name, i]));

    return packages.map((rawPackage) => {
        const rawVersion = useLatestVersion
            ? rawPackage.versions[0]
            : rawPackage.versions.find((v) => v.version_number === versionMap[rawPackage.full_name])

        if (!rawVersion) {
            return undefined;
        }

        const combo = new ThunderstoreCombo();
        combo.setMod(ThunderstoreMod.parseFromThunderstoreData(rawPackage));
        combo.setVersion(ThunderstoreVersion.parseFromThunderstoreData(rawVersion));
        return combo;
    }).filter(
        (c): c is ThunderstoreCombo => c !== undefined
    ).sort((a, b) => {
        // Sort combos to match the original order of dependency strings.
        const positionA = modOrderMap.get(a.getMod().getFullName()) || -1;
        const positionB = modOrderMap.get(b.getMod().getFullName()) || -1;
        return positionA - positionB;
    });
}

export async function getLastPackageListUpdateTime(community: string) {
    const hash = await db.indexHashes.where({community}).first();
    return hash ? hash.date_updated : undefined;
}

export async function getVersionAsThunderstoreVersion(community: string, packageName: string, versionNumber: string) {
    const version = await getPackgeVersionFromDatabase(community, packageName, versionNumber);
    return ThunderstoreVersion.parseFromThunderstoreData(version);
}

export async function hasEntries(community: string): Promise<boolean> {
    if (await db.indexHashes.where({community}).count()) {
        return true;
    }

    if (await db.packages.where({community}).count()) {
        return true;
    }

    return false;
}

export async function isLatestPackageListIndex(community: string, hash: string) {
    return Boolean(
        await db.indexHashes.where({community, hash}).count()
    );
}

export function selectPackageIdsToPrune(
    storedKeys: [string, string][],
    fetchedFullNames: Set<string>
): [string, string][] {
    return storedKeys.filter(([, fullName]) => !fetchedFullNames.has(fullName));
}

export async function pruneRemovedMods(community: string, fetchedFullNames: Set<string>) {
    const retainedNames = new Set(fetchedFullNames);
    if (isGhostGame(community)) GHOST_PACKAGES.forEach(name => retainedNames.add(name));
    await db.transaction('rw', db.packages, db.summaries, async () => {
        const storedKeys = await db.packages.where({community}).primaryKeys();
        const toDelete = selectPackageIdsToPrune(storedKeys, retainedNames);
        await db.packages.bulkDelete(toDelete);
        await db.summaries.bulkDelete(toDelete);
    });
}

export async function resetCommunity(community: string) {
    await db.transaction('rw', db.packages, db.summaries, db.indexHashes, async () => {
        const packageIds = await db.packages.where({community}).primaryKeys();
        await db.packages.bulkDelete(packageIds);
        await db.summaries.where({community}).delete();
        await db.indexHashes.where({community}).delete();
    });
}

export async function upsertPackageListChunk(community: string, packageChunk: any[]) {
    const newPackages: DexiePackage[] = packageChunk.map((pkg) => Object.assign(pkg, {community}));
    const newSummaries: DexieSummary[] = packageChunk.map((pkg) => toSummary(community, pkg));
    await db.transaction('rw', db.packages, db.summaries, async () => {
        await db.packages.bulkPut(newPackages);
        await db.summaries.bulkPut(newSummaries);
    });
}

export async function setLatestPackageListIndex(community: string, hash: string) {
    await db.indexHashes.put({community, hash, date_updated: new Date()});
}

export async function getPackageFromDatabase(community: string, packageName: string) {
    const pkg = await db.packages.where({community, full_name: packageName}).first();

    if (!pkg) {
        throw new Error(`Couldn't find package "${packageName}" in ${community} packages`);
    }

    return pkg;
}

async function getPackgeVersionFromDatabase(community: string, packageName: string, versionNumber: string) {
    const pkg = await getPackageFromDatabase(community, packageName);
    const ver = pkg.versions.find((v) => v.version_number === versionNumber);

    if (!ver) {
        throw new Error(`Couldn't find version "${versionNumber}" of package "${packageName}" in ${community} packages`);
    }

    return ver;
}

import Profile, {ImmutableProfile} from '../model/Profile';
import R2Error from '../model/errors/R2Error';
import Game from '../model/game/Game';
import FsProvider from '../providers/generic/file/FsProvider';
import GameRunnerProvider from '../providers/generic/game/GameRunnerProvider';
import GameDirectoryResolverProvider from '../providers/ror2/game/GameDirectoryResolverProvider';
import ManagerSettings from '../r2mm/manager/ManagerSettings';
import ModLinker from '../r2mm/manager/ModLinker';
import {Platform} from '../assets/data/ecosystemTypes';
import LinuxGameDirectoryResolver from '../r2mm/manager/linux/GameDirectoryResolver';
import {LaunchType} from "../model/real_enums/launch/LaunchType";
import path from "../providers/node/path/path";
import PathResolver from "../r2mm/manager/PathResolver";
import appWindow from '../providers/node/app/app_window';
import InteractionProvider from "../providers/ror2/system/InteractionProvider";
import { TypedEventEmitter } from "./TypedEventEmitter";

import {requireGhostSetupBeforeLaunch} from '../ghost/GhostRequiredSetup';

export enum LaunchMode { VANILLA, MODDED };

export const OnGameLaunch = new TypedEventEmitter<{ game: Game, profile: Profile, mode: LaunchMode }>();

export const launch = async (game: Game, profile: Profile, mode: LaunchMode): Promise<void> => {
    if(mode===LaunchMode.MODDED)await requireGhostSetupBeforeLaunch(game,profile.asImmutableProfile());
    // This event is used for analytics by TMM
    await OnGameLaunch.emit({game, profile, mode});

    const error = (mode === LaunchMode.MODDED)
        ? await GameRunnerProvider.instance.startModded(game, profile)
        : await GameRunnerProvider.instance.startVanilla(game, profile);

    if (error instanceof R2Error) {
        throw error;
    }
};

export const linkProfileFiles = async (game: Game, profile: ImmutableProfile): Promise<void> => {
    const settings = await ManagerSettings.getSingleton(game);

    const newLinkedFiles = await ModLinker.link(profile, game);
    if (newLinkedFiles instanceof R2Error) {
        throw newLinkedFiles;
    }

    await settings.setLinkedFiles(newLinkedFiles);
};

/**
 * Non-fatal wrapper around linkProfileFiles.
 * Syncs mod loader root files from the profile to the game directory.
 * Failures are logged but do not propagate, so callers such as install/update flows
 * won't fail if the game directory is not configured or the files are locked by a running game.
 */
export const syncProfileRootFiles = async (game: Game, profile: ImmutableProfile): Promise<void> => {
    try {
        await linkProfileFiles(game, profile);
    } catch (e) {
        console.warn('Failed to sync root mod files to game directory:', e);
    }
};

export const setGameDirIfUnset = async (game: Game): Promise<void> => {
    const settings = await ManagerSettings.getSingleton(game);
    const currentDir = settings.getContext().gameSpecific.gameDirectory;

    if (currentDir === null) {
        const dir = await GameDirectoryResolverProvider.instance.getDirectory(game);
        if (dir instanceof R2Error) {
            throw dir;
        }

        await settings.setGameDirectory(dir);
    }
};

export const throwIfNoGameDir = async (game: Game): Promise<void> => {
    const error = new R2Error(
        `Failed to start ${game.displayName}`,
        `The ${game.displayName} folder does not exist`,
        `Set the ${game.displayName} folder in the Settings screen`
    );

    const resolverGameDir = await GameDirectoryResolverProvider.instance.getDirectory(game);
    if (resolverGameDir instanceof R2Error) {
        throw error;
    }

    const settings = await ManagerSettings.getSingleton(game);
    const ctcGameDir = settings.getContext().gameSpecific.gameDirectory!;
    const ctxGameDirExists = await FsProvider.instance.exists(ctcGameDir);

    if (!ctxGameDirExists) {
        throw error;
    }
};

export async function isProtonRequired(activeGame: Game) {
    if (appWindow.getPlatform() !== 'linux') {
        return false;
    }
    return [Platform.STEAM, Platform.STEAM_DIRECT].includes(activeGame.activePlatform.storePlatform)
        ? await (GameDirectoryResolverProvider.instance as LinuxGameDirectoryResolver).isProtonGame(activeGame)
        : false;
}

export async function getDeterminedLaunchType(game: Game, launchType: LaunchType): Promise<LaunchType> {
    if (launchType !== LaunchType.AUTO) {
        return launchType;
    }
    if (await isProtonRequired(game)) {
        return LaunchType.PROTON;
    }
    return LaunchType.NATIVE;
}

export async function isManagerRunningOnFlatpak(): Promise<boolean> {
    const env = await InteractionProvider.instance.getEnvironmentVariables();
    return !!env.FLATPAK_ID;
}

export async function getProvidedWrapperArguments(game: Game): Promise<string> {
    return Promise.resolve()
        .then(async () => await (GameDirectoryResolverProvider.instance as LinuxGameDirectoryResolver).getLaunchArgs(game))
        .then(launchArgs => {
            if (typeof launchArgs !== 'string') {
                throw launchArgs;
            }
            return launchArgs.replaceAll('\\"', '"');
        });
}

/**
 * Returns true if any wrapper script is set. The wrapper does not need to be valid.
 * @param game - The game to check for the set launch arguments
 */
export async function areAnyWrapperArgumentsProvided(game: Game): Promise<boolean> {
    // We don't care about the paths here
    // We can assume that if a wrapper is provided then it's pointing to an existing install (old or new)
    const flatpakWrapper = 'web_start_wrapper.sh';
    const linuxWrapper = 'linux_wrapper.sh';
    return getProvidedWrapperArguments(game)
        .then(launchArgs => (launchArgs.includes(linuxWrapper) || launchArgs.includes(flatpakWrapper)))
        .catch(() => false);
}

export async function areWrapperArgumentsProvided(game: Game): Promise<boolean> {
    const isFlatpak = await isManagerRunningOnFlatpak();
    const flatpakWrapper = path.join(PathResolver.MOD_ROOT, 'web_start_wrapper.sh');
    const linuxWrapper = path.join(PathResolver.MOD_ROOT, 'linux_wrapper.sh');
    const appropriateWrapper = isFlatpak ? flatpakWrapper : linuxWrapper;
    return getProvidedWrapperArguments(game)
        .then(launchArgs => launchArgs.includes(appropriateWrapper))
        .catch(() => false);
}

export async function getWrapperLaunchArgs(): Promise<string> {
    return `"${path.join(PathResolver.MOD_ROOT, appWindow.getPlatform() === 'darwin' ? 'macos_proxy' : 'linux_wrapper.sh')}" %command%`;
}

