test('actual second-mod ZIP installs, upgrades and preserves config and the main Ghost suite', async () => {
    const source=process.env.GHOST_PACK_FIXTURE;
    if (!source) throw new Error('GHOST_PACK_FIXTURE must point to the extracted final suite package');
    const base=await fs.mkdtemp(path.join(os.tmpdir(),'ghost-install-'));
    providePathImplementation(()=>path);
    FsProvider.provide(()=>new NodeFs());
    const game=Object.values(ecosystem.games).flatMap((g:any)=>g.r2modman || []).find((g:any)=>g.settingsIdentifier==='Valheim')!;
    const installer=new InstallRulePluginInstaller({gameName:'Valheim',rules:game.installRules,relativeFileExclusions:game.relativeFileExclusions});
    const mod=new ManifestV2();mod.setName('Ghost-GhostSmelterControl');mod.setAuthorName('Ghost');mod.setVersionNumber(new VersionNumber('1.0.0'));
    const profile={joinToProfilePath:(...p:string[])=>path.join(base,...p),getProfileName:()=> 'Fixture',getProfilePath:()=>base} as any;
    try {
        await fs.mkdir(path.join(base,'BepInEx/config'),{recursive:true});
        await fs.mkdir(path.join(base,'BepInEx/plugins/Unrelated'),{recursive:true});
        await fs.mkdir(path.join(base,'BepInEx/plugins/Ghost-GhostValheimSuite'),{recursive:true});
        await fs.writeFile(path.join(base,'BepInEx/plugins/Ghost-GhostValheimSuite/Main.dll'),'unchanged main suite');
        await fs.writeFile(path.join(base,'BepInEx/config/user.cfg'),'preserve existing settings');
        await fs.writeFile(path.join(base,'BepInEx/plugins/Unrelated/Other.dll'),'preserve other mods');
        const args={mod,profile,packagePath:source};
        await installer.install(args);
        const walk=async(dir:string):Promise<string[]>=>{const files:string[]=[];for(const e of await fs.readdir(dir,{withFileTypes:true})){const p=path.join(dir,e.name);if(e.isDirectory())files.push(...await walk(p));else files.push(p)}return files;};
        const sourceDlls=(await walk(source)).filter(p=>p.endsWith('.dll'));
        const installed=(await walk(path.join(base,'BepInEx/plugins/Ghost-GhostSmelterControl'))).filter(p=>p.endsWith('.dll'));
        expect(sourceDlls).toHaveLength(1);expect(installed).toHaveLength(1);
        for(const dll of sourceDlls){const dest=installed.find(p=>path.basename(p)===path.basename(dll))!;expect(createHash('sha256').update(await fs.readFile(dest)).digest('hex')).toBe(createHash('sha256').update(await fs.readFile(dll)).digest('hex'));}
        await installer.uninstall(args);
        mod.setVersionNumber(new VersionNumber('1.0.1'));
        await installer.install(args);
        expect((await walk(path.join(base,'BepInEx/plugins/Ghost-GhostSmelterControl'))).filter(p=>p.endsWith('.dll'))).toHaveLength(1);
        expect(await fs.readFile(path.join(base,'BepInEx/plugins/Ghost-GhostValheimSuite/Main.dll'),'utf8')).toBe('unchanged main suite');
        expect(await fs.readFile(path.join(base,'BepInEx/config/user.cfg'),'utf8')).toBe('preserve existing settings');
        expect(await fs.readFile(path.join(base,'BepInEx/plugins/Unrelated/Other.dll'),'utf8')).toBe('preserve other mods');
    } finally {await fs.rm(base,{recursive:true,force:true});}
});

