    }finally{await rm(dir,{recursive:true,force:true});}
});
test.each(['hash','short','oversize','http','stream'])('invalid %s download never leaves an installable archive',async mode=>{
    const dir=await mkdtemp(path.join(os.tmpdir(),'ghost-self-update-test-'));
    try{
        const file=path.join(dir,'runtime.zip');
        let response:any=new Response(mode==='short'?data.subarray(1):mode==='oversize'?Buffer.concat([data,data]):Buffer.alloc(data.length,1));
        if(mode==='http')response=new Response(null,{status:503});
        if(mode==='stream')response={ok:true,headers:new Headers(),body:new ReadableStream({start(c){c.error(new Error('connection lost'));}})};
        await expect(downloadVerifiedClient(release,file,async()=>response,()=>{})).rejects.toThrow();
        await expect(access(file)).rejects.toThrow();
    }finally{await rm(dir,{recursive:true,force:true});}
});

