function setup(){
 const states:any[]=[];let onError!:()=>void;const error=new Promise<void>(r=>onError=r);
 const wc={send:(_key:string,state:any)=>{states.push({...state});if(state.phase==='error')onError();}};
 const window={webContents:wc,isDestroyed:()=>false,once:vi.fn()} as any;
 registerGhostSelfUpdater(window,()=> 'ghostvault://v1/install/Ghost-GhostValheimSuite/latest');
 const event={sender:wc};
 return {states,error,prepare:()=>native.handlers.get('ghost-self-update-prepare')!(event),decide:(v:string)=>native.handlers.get('ghost-self-update-decision')!(event,v)};
}
function acknowledgeHelper(){
 const child=Object.assign(new EventEmitter(),{exitCode:null,unref:vi.fn()});
 native.spawn.mockImplementation((_exe:string,args:string[])=>{writeFileSync(args[args.indexOf('-ReadyPath')+1]!,'ready');return child;});return child;
}
test.each(['same','older','offline'])('%s startup continues without restarting or spawning a helper',async mode=>{
 native.fetch.mockImplementation(async()=>{if(mode==='offline')throw Error('offline');return new Response(JSON.stringify({...release,version:mode==='same'?'1.0.7':'1.0.6',downloadUrl:release.downloadUrl.replaceAll('1.0.8',mode==='same'?'1.0.7':'1.0.6')}));});
 const s=setup();expect(await s.prepare()).toBe(true);expect(s.states.at(-1).phase).toBe('idle');expect(native.quit).not.toHaveBeenCalled();expect(native.spawn).not.toHaveBeenCalled();
});
test('new release downloads once, waits for a ready helper, preserves install request and restarts',async()=>{
 native.fetch.mockImplementation(async(url:string)=>url.includes('client-release.json')?new Response(JSON.stringify(release)):new Response(payload));
 const child=acknowledgeHelper(),s=setup();
 const first=s.prepare(),second=s.prepare();expect(await first).toBe(false);expect(await second).toBe(false);
 expect(native.fetch).toHaveBeenCalledTimes(2);expect(native.spawn).toHaveBeenCalledTimes(1);expect(native.quit).toHaveBeenCalledOnce();expect(child.unref).toHaveBeenCalledOnce();
 expect(s.states.map(x=>x.phase)).toEqual(expect.arrayContaining(['checking','downloading','installing']));
 const args=native.spawn.mock.calls[0]![1];expect(args).toContain(release.sha256);expect(args).toContain('ghostvault://v1/install/Ghost-GhostValheimSuite/latest');
 expect(native.spawn.mock.calls[0]![2]).toMatchObject({detached:true,windowsHide:true,stdio:'ignore'});
});
test('corrupt download exposes retry/continue and never restarts the current app',async()=>{
 native.fetch.mockImplementation(async(url:string)=>url.includes('client-release.json')?new Response(JSON.stringify(release)):new Response(Buffer.alloc(payload.length,0)));
 const s=setup(),pending=s.prepare();await s.error;await s.decide('continue');expect(await pending).toBe(true);
 expect(native.spawn).not.toHaveBeenCalled();expect(native.quit).not.toHaveBeenCalled();expect(s.states.at(-1).phase).toBe('idle');
});
test('a previous failed replacement does not produce a restart loop',async()=>{
 await mkdir(path.join(directory,'GhostR2'));await writeFile(path.join(directory,'GhostR2/self-update-result.json'),JSON.stringify({status:'failed',version:'1.0.8',time:Date.now()}));
 native.fetch.mockResolvedValue(new Response(JSON.stringify(release)));
 const s=setup(),pending=s.prepare();await s.error;await s.decide('continue');expect(await pending).toBe(true);
 expect(native.fetch).toHaveBeenCalledTimes(1);expect(native.spawn).not.toHaveBeenCalled();expect(native.quit).not.toHaveBeenCalled();
});
test('unexpected IPC sender cannot start an update',async()=>{
 setup();expect(()=>native.handlers.get('ghost-self-update-prepare')!({sender:{}})).toThrow('Unexpected');expect(native.fetch).not.toHaveBeenCalled();
});

