test('strict second-package protocol resolves and download trust cannot cross packages', async () => {
    const link = 'ghostvault://v1/install/Ghost-GhostSmelterControl/latest';
    expect(parseGhostProtocolTarget(link)).toEqual({ packageName: GHOST_SMELTER_PACKAGE, version: 'latest' });
    expect(isTrustedGhostDownloadUrl(ghostSmelterDownloadUrl('1.0.0'), '1.0.0', GHOST_SMELTER_PACKAGE)).toBe(true);
    expect(isTrustedGhostDownloadUrl(ghostSmelterDownloadUrl('1.0.0'), '1.0.0', GHOST_PACKAGE)).toBe(false);
    expect(isTrustedGhostDownloadUrl(ghostSmelterDownloadUrl('1.0.0') + '?x', '1.0.0', GHOST_SMELTER_PACKAGE)).toBe(false);
    expect(() => parseGhostProtocolTarget(link.replace('latest', '../latest'))).toThrow();
    vi.spyOn(axios, 'get').mockImplementation(async (url: any) => {
        const r = String(url).includes('/smelter-') ? release() : { ...release(), file: 'downloads/Ghost-GhostValheimSuite-1.0.0.zip' };
        return { data: String(url).endsWith('-release.json') || String(url).endsWith('/release.json') ? r : [r] };
    });
    const combo = await ThunderstoreCombo.fromProtocol(link, game);
    expect(combo).toBeInstanceOf(ThunderstoreCombo);
    expect((combo as ThunderstoreCombo).getMod().getFullName()).toBe(GHOST_SMELTER_PACKAGE);
});
